const boundary = 'divider';
const docName = $input.first().json.document_name;
const folderId = $input.first().json.drive_folder_id;
const htmlContent = $input.first().json.html_content;

const metadata = JSON.stringify({
  name: docName,
  mimeType: "application/vnd.google-apps.document",
  parents: [folderId]
});

const htmlWithStyles = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <style>
    /* Add bottom margin to block elements for spacing */
    p,
    ul,
    ol,
    table,
    h1,
    h2,
    h3,
    h4,
    h5,
    h6 {
      margin-bottom: 10pt;
    }

    h2 {
      margin-top: 20pt;
    }

    /* Prevent margin collapse issues or excessive space inside lists */
    li {
       margin-bottom: 2pt; /* Optional: small space between list items */
    }

    /* Remove margin from the last child within common containers if needed */
    /* This might be overly aggressive, test without it first */
    /*
    body > *:last-child,
    li > *:last-child {
       margin-bottom: 0;
    }
    */
  </style>
</head>
<body>
  ${htmlContent}
</body>
</html>
`;

// Construct the body with literal \r\n ONLY
let body = `--${boundary}\r\n`;
body += `Content-Type: application/json; charset=UTF-8\r\n`;
body += `\r\n`; // Blank line
body += `${metadata}\r\n`;
body += `--${boundary}\r\n`;
body += `Content-Type: text/html\r\n`;
body += `\r\n`; // Blank line
body += `${htmlWithStyles}\r\n`; // Add the HTML content
body += `--${boundary}--\r\n`; // Final boundary

return {
  rawData: body 
};

// Convert seconds (e.g. "37.600") into [MM:SS] format (e.g. [00:37])
function formatTime(secondsStr) {
  const totalSeconds = Math.floor(parseFloat(secondsStr) || 0);
  const minutes = Math.floor(totalSeconds / 60).toString().padStart(2, '0');
  const seconds = (totalSeconds % 60).toString().padStart(2, '0');
  return `[${minutes}:${seconds}]`;
}

// Recursively extract timestamp + text from any JSON structure
function extractTimestamps(obj) {
  let results = [];

  if (Array.isArray(obj)) {
    for (const item of obj) {
      results = results.concat(extractTimestamps(item));
    }
  } else if (typeof obj === 'object' && obj !== null) {
    if (obj.text && typeof obj.text === 'string' && obj.start !== undefined) {
      const timeTag = formatTime(obj.start);
      const cleanText = obj.text.trim();
      if (cleanText) {
        results.push(`${timeTag} ${cleanText}`);
      }
    }
    for (const key in obj) {
      if (key !== 'text' && key !== 'start') {
        results.push(...extractTimestamps(obj[key]));
      }
    }
  }

  return results;
}

// Read n8n input and process it
const inputData = $input.all();
const lines = extractTimestamps(inputData);

// Join into a single string separated by newlines (\n)
const formattedText = lines.join("\n");

return [{ json: { formattedText } }];
